      "path": "lib/tray.js",
      "content": "import { writeFileSync, mkdirSync, existsSync } from "node:fs";
import { homedir } from "node:os";
import { join } from "node:path";
import { distroName, runPowerShell } from "./wsl-host.js";

const AHK_HEADER = "; Generated by dsh-wsl-tray — requires AutoHotkey v2+";

// First match wins, so order is the priority.
//
// The WSL checkout leads deliberately. These scripts are what the recovery path
// runs when dsh will not start, and the copy they read has to be the copy that
// actually gets updated. Two checkouts of the same repository existed, edits
// landed in the one under src, and the Windows one silently drifted — far
// enough that a working relay fix was overwritten by a later sync and the loss
// only surfaced because someone went looking. Leading with the WSL path means
// the recovery runs what git has, not what a stale directory happens to hold.
//
// The Windows paths stay as fallbacks: if the WSL checkout is ever removed, a
// recovery that still works from the other copy beats one that finds nothing.
// Candidates are derived, not pinned: $DSH_WSL_KIT wins, then a sibling checkout of
// this plugin, then the usual WSL and Windows locations under the current user's home.
const FALLBACK_KIT_PATHS = (() => {
  const home = process.env.HOME || "/home";
  const winHome = process.env.WSL_WINDOWS_HOME || "/mnt/c/Users";
  const out = [];
  if (process.env.DSH_WSL_KIT) out.push(process.env.DSH_WSL_KIT);
  out.push(`${home}/src/dsh-wsl-kit`);
  // /mnt/c/Users/<user>/... — discover the Windows profile name rather than assume it
  try {
    for (const name of readdirSync(winHome)) {
      out.push(`${winHome}/${name}/Desktop/AIFullStackDevelopment/dsh-wsl-kit`);
      out.push(`${winHome}/${name}/Desktop/dsh-wsl-kit`);
    }
  } catch {
    // /mnt/c may not be mounted (native Linux, CI) — the WSL path above still applies
  }
  return out.filter((p, i) => p && out.indexOf(p) === i);
})();

export function notWsl() {
  return { ok: false, error: "not running in WSL" };
}

export function parameters() {
  return {
    type: "object",
    additionalProperties: false,
    properties: {
      action: {
        type: "string",
        enum: ["status", "install_scripts", "install_tray"],
        description:
          "status = report paths; install_scripts = PS1 + desktop shortcut; install_tray = AHK v2 tray icon + PS1.",
      },
      url: { type: "string", description: "Browser URL (default http://127.0.0.1:3081 via kit relay; dsh itself listens on 3080 inside WSL)." },
      kitPath: { type: "string", description: "Override path to dsh-wsl-kit (or set DSH_WSL_KIT)." },
    },
  };
}

export function outputSchema() {
  return { type: "object", additionalProperties: true };
}

export function format(v) {
  const lines = [`wsl_tray action=${v.action || "?"} ok=${v.ok}`];
  if (v.dir) lines.push(`dir: ${v.dir}`);
  if (v.kitPath) lines.push(`kitPath: ${v.kitPath}`);
  if (v.startPs1) lines.push(`startPs1: ${v.startPs1}`);
  if (v.trayAhk) lines.push(`trayAhk: ${v.trayAhk}`);
  if (v.autohotkeyPath) lines.push(`autohotkey: ${v.autohotkeyPath}`);
  if (v.shortcutHint) lines.push(`shortcut: ${v.shortcutHint}`);
  for (const a of v.advice || []) lines.push(`- ${a}`);
  if (v.error) lines.push(`error: ${v.error}`);
  return lines.join("\n");
}

/** Resolve dsh-wsl-kit root: kitPath arg → DSH_WSL_KIT → existsSync candidates. */
export function resolveKitPath({
  kitPath = "",
  env = process.env,
  exists = existsSync,
  candidates = FALLBACK_KIT_PATHS,
} = {}) {
  const fromArg = String(kitPath || "").trim();
  if (fromArg && exists(join(fromArg, "scripts", "restart-dsh-web.sh"))) {
    return { ok: true, path: fromArg.replace(/\/+$/, ""), source: "arg" };
  }
  const fromEnv = String(env.DSH_WSL_KIT || "").trim();
  if (fromEnv && exists(join(fromEnv, "scripts", "restart-dsh-web.sh"))) {
    return { ok: true, path: fromEnv.replace(/\/+$/, ""), source: "env" };
  }
  for (const c of candidates) {
    if (exists(join(c, "scripts", "restart-dsh-web.sh"))) {
      return { ok: true, path: c.replace(/\/+$/, ""), source: "fallback" };
    }
  }
  return { ok: false, path: "", source: "missing" };
}

/**
 * A shell command as the contents of a PowerShell single-quoted string.
 *
 * The command contains single quotes of its own -- sed 's/\r$//' appears twice
 * in every one of them -- and an unescaped one ends the PowerShell string early.
 * The result is not an error but a mangled invocation: the pieces get reassembled
 * into something bash rejects or, worse, partly runs. test-path on the launcher
 * said the file existed and the file was still useless.
 *
 * PowerShell escapes a single quote inside a single-quoted string by doubling it.
 */
function psQuote(command) {
  return String(command).replace(/'/g, "''");
}

export function ps1Body(distro, url, kitPath) {
  const restart = `${kitPath}/scripts/restart-dsh-web.sh`;
  const revive = `${kitPath}/scripts/revive-dsh.sh`;
  const health = `${kitPath}/scripts/check-dsh-health.sh`;
  const alive = `${kitPath}/scripts/dsh-web-alive.inc.sh`;
  // The PATH assignment is quoted, and that is load-bearing.
  //
  // wsl.exe launched from Windows appends the Windows PATH to the Linux one, so
  // $PATH here carries "/mnt/c/Program Files (x86)/cloudflared/". Unquoted, those
  // parentheses are a bash syntax error and the command line dies before the
  // first sed runs:
  //
  //   -c: line 1: syntax error near unexpected token `('
  //
  // The launcher therefore appeared to do nothing. Get-DshTokenUrl was never
  // affected because it does not touch PATH, which is why the token could be
  // read while the restart never happened.
  const bashRestart = `if [ -f '${revive}' ]; then bash '${revive}'; else bash '${restart}'; fi`;
  const bashHealth = `bash '${health}'; echo; read -n 1 -p 'Press any key...'`;
  // Bare :3081 is 401 on dsh ≥0.1.2 — never open without ?token= from /tmp/dsh-ui-url.
  return [
    "# Generated by dsh-wsl-tray — start dsh web (WSL) + localhost relay, then open token URL.",
    "# NEVER bookmark bare http://127.0.0.1:3081/ (401). Always open /tmp/dsh-ui-url after restart.",
    `# kitPath: ${kitPath}`,
    `$distro = '${distro.replace(/'/g, "''")}'`,
    "function Get-DshTokenUrl {",
    "  $fromFile = (wsl.exe -d $distro -- bash -lc 'cat /tmp/dsh-ui-url 2>/dev/null').Trim()",
    "  if ($fromFile -match 'token=') { return $fromFile }",
    "  return ''",
    "}",
    "function Start-DshWsl {",
    // `&` rather than Start-Process -ArgumentList.
    //
    // Start-Process joins an -ArgumentList array with spaces and quotes nothing,
    // so the command string -- which is full of spaces and semicolons -- arrived
    // at bash as several argv entries and only the tail of it ran. Measured:
    //
    //   Start-Process ... @(..., 'bash', '-lc', 'echo ARG_TEST; echo second; whoami')
    //     -> prints "second" and the user name; ARG_TEST never ran
    //   & wsl.exe -d $d -- bash -lc 'echo ARG_TEST; echo second; whoami'
    //     -> prints all three
    //
    // That is why the desktop shortcut did nothing: the recovery path had never
    // worked, and the moment it was needed was the moment everything else was
    // already broken.
    //
    // The console flash is handled on the shortcut instead, where WindowStyle
    // applies to the PowerShell host that owns the window.
    `  & wsl.exe -d $distro -- bash -lc '${psQuote(bashRestart)}'`,
    "  Start-Sleep -Seconds 12",
    "  $url = Get-DshTokenUrl",
    "  if ($url) {",
    // Put it on the clipboard as well as opening it. The token is per-process,
    // so the clipboard is the one route that survives everything else going
    // wrong: if the browser opens into the wrong profile, or does not open at
    // all, the address is already somewhere it can be pasted. The detached
    // restart has always done this through dsh_open_browser; this path opened
    // the URL and stopped, so the safety net was missing on exactly the route a
    // person reaches for when nothing else works.
    "    Set-Clipboard -Value $url",
    "    Start-Process $url",
    "    Write-Host ('opened ' + $url)",
    "    Write-Host 'the same URL is on the clipboard'",
    "  } else {",
    "    Write-Host 'FAIL: no token URL in /tmp/dsh-ui-url — re-run restart-dsh-web.sh'",
    "  }",
    "}",
    "function Open-DshUi {",
    "  $url = Get-DshTokenUrl",
    "  if ($url) { Set-Clipboard -Value $url; Start-Process $url } else {",
    "    Write-Host 'No fresh token — running Start/Restart first…'",
    "    Start-DshWsl",
    "  }",
    "}",
    "function Show-DshHealth {",
    `  & wsl.exe -d $distro -- bash -lc '${psQuote(bashHealth)}'`,
    "}",
    "Start-DshWsl",
  "Read-Host 'Press Enter to close this window'",
    "",
  ].join("\n");
}

export function openUiPs1Body(distro) {
  return [
    "# Generated by dsh-wsl-tray — open ONLY the current token URL (never bare :3081).",
    `$distro = '${distro.replace(/'/g, "''")}'`,
    "$url = (wsl.exe -d $distro -- bash -lc 'cat /tmp/dsh-ui-url 2>/dev/null').Trim()",
    "if ($url -match 'token=') { Start-Process $url }",
    "else {",
    "  Write-Host 'FAIL: /tmp/dsh-ui-url missing or has no token. Run Start / Restart dsh first.'",
    "  Start-Sleep -Seconds 4",
    "}",
    "",
  ].join("\n");
}

export function ahkBody(distro, url, ps1WinPath, kitPath, healthPs1WinPath, openUiPs1WinPath) {
  const ps1Esc = ps1WinPath.replace(/\\/g, "\\\\");
  const healthEsc = (healthPs1WinPath || ps1WinPath).replace(/\\/g, "\\\\");
  const openEsc = (openUiPs1WinPath || ps1WinPath).replace(/\\/g, "\\\\");
  return [
    AHK_HEADER,
    "#Requires AutoHotkey v2.0",
    "#SingleInstance Force",
    `; kitPath: ${kitPath}`,
    "TraySetIcon()",
    "A_TrayMenu.Add('Open dsh web (token URL)', (*) => Run('powershell.exe -NoProfile -ExecutionPolicy Bypass -File \"" +
      openEsc +
      "\"'))",
    "A_TrayMenu.Add('Start / Restart dsh (WSL)', (*) => Run('powershell.exe -NoProfile -ExecutionPolicy Bypass -File \"" +
      ps1Esc +
      "\"'))",
    "A_TrayMenu.Add('Health check', (*) => Run('powershell.exe -NoProfile -ExecutionPolicy Bypass -File \"" +
      healthEsc +
      "\"'))",
    "A_TrayMenu.Add('Quit tray', (*) => ExitApp())",
    "A_TrayMenu.Default := 'Open dsh web (token URL)'",
    "A_TrayMenu.ClickCount := 1",
    `; Distro: ${distro}`,
    "",
  ].join("\n");
}

export function healthPs1Body(distro, kitPath) {
  const health = `${kitPath}/scripts/check-dsh-health.sh`;
  const alive = `${kitPath}/scripts/dsh-web-alive.inc.sh`;
  const bashHealth = `bash '${health}'; echo; read -n 1 -p 'Press any key...'`;
  return [
    "# Generated by dsh-wsl-tray — run kit check-dsh-health.sh inside WSL.",
    `$distro = '${distro.replace(/'/g, "''")}'`,
    // `&`, not Start-Process -ArgumentList: see the note in ps1Body. The array
    // form splits the command string on its own spaces and bash only sees the
    // tail of it.
    `& wsl.exe -d $distro -- bash -lc '${psQuote(bashHealth)}'`,
    "",
    "Read-Host 'Press Enter to close'",
    "",
  ].join("\n");
}

async function detectAutoHotkey() {
  try {
    const { stdout } = await runPowerShell(
      "(Get-Command AutoHotkey64.exe, AutoHotkey.exe -ErrorAction SilentlyContinue | Select-Object -First 1 -ExpandProperty Source)",
      { timeoutMs: 8_000 },
    );
    return stdout.trim().split(/\r?\n/).map((s) => s.trim()).find(Boolean) || "";
  } catch {
    return "";
  }
}

async function createDesktopShortcut(startPs1Win) {
  try {
    // The value goes into a single-quoted PowerShell string, so the only
    // character that needs doubling is the single quote itself.
    //
    // It used to double backslashes as well. That was harmless while the
    // argument was a Linux path with none, and wrong the moment it became a UNC
    // path: the shortcut was written with \\\\wsl.localhost\\Ubuntu-24.04\\...,
    // which is not a path any Windows API resolves. The path is only useful if
    // it survives this function byte for byte.
    const arg = String(startPs1Win).replace(/'/g, "''");

    // Confirm the path resolves from Windows before writing it into a shortcut.
    //
    // A .lnk pointing at a host that does not exist fails silently: no window,
    // no error, nothing left to read afterwards. This one was written with the
    // wrong distro name -- \\wsl.localhost\WSL\... -- and double-clicking it did
    // nothing at all. That is the worst possible shape for a recovery entry
    // point: the moment it is needed is the moment nothing else works either,
    // so there is nothing else to tell you why. Better to write no shortcut and
    // say so.
    const check = await runPowerShell(
      `if (Test-Path '${arg}') { 'RESOLVES' } else { 'MISSING' }`,
      { timeoutMs: 15_000 },
    );
    if (!String(check.stdout).includes("RESOLVES")) {
      return `(shortcut NOT written: ${startPs1Win} does not resolve from Windows)`;
    }

    await runPowerShell(
      `$ws = New-Object -ComObject WScript.Shell; $s = $ws.CreateShortcut("$env:USERPROFILE\\Desktop\\DSH WSL.lnk"); $s.TargetPath = 'powershell.exe'; $s.Arguments = '-NoProfile -ExecutionPolicy Bypass -File "' + '${arg}' + '"'; $s.Save()`,
      { timeoutMs: 20_000 },
    );
    return "Desktop\\DSH WSL.lnk";
  } catch {
    return "(shortcut creation failed — use startPs1 manually)";
  }
}

/**
 * A Linux path as something Windows can open.
 *
 * /mnt/c/... becomes C:\. Everything else -- the files this writes live under
 * $HOME/.dsh/tray, which is not on a drive letter -- has to go through the WSL
 * share, because Windows cannot open /home/<user>/... at all. Verified with
 * Test-Path: 'C:\Users\<user>\.dsh\tray\x.ps1' and '/home/<user>/.dsh/tray/x.ps1'
 * both fail; '\\wsl.localhost\<distro>\home\<user>\.dsh\tray\x.ps1' succeeds.
 *
 * This returned such paths unchanged before, and the desktop shortcut was
 * created with -File "/home/<user>/.dsh/tray/start-dsh-web.ps1". The shortcut
 * had never worked: double-clicking it did nothing, which is the worst possible
 * failure for a recovery entry point, because the moment you need it is the
 * moment nothing else works either.
 */
function wslPathToWin(path, distro = distroName()) {
  const drive = path.match(/^\/mnt\/([a-z])\/(.*)$/i);
  if (drive) return `${drive[1].toUpperCase()}:\\${drive[2].replace(/\//g, "\\")}`;
  if (path.startsWith("/")) {
    // UNC, and not \\wsl$ -- the older form works too, but \\wsl.localhost is
    // the one Microsoft documents and the one that resolves without the dollar.
    return `\\\\wsl.localhost\\${distro}${path.replace(/\//g, "\\")}`;
  }
  return path;
}

/**
 * Write a file for Windows PowerShell 5.1 to read.
 *
 * The BOM is required, not cosmetic. Without it powershell.exe decodes a .ps1
 * as the system ANSI code page -- GBK here -- and GBK is multi-byte, so a
 * lead byte consumes the following byte and the whole stream shifts. Any
 * non-ASCII character inside a single-quoted string then swallows the quote
 * that was meant to close it:
 *
 *   Start-DshWeb.ps1:24  字符串缺少终止符: '
 *
 * The generated health script had a dash only in a comment and worked; the
 * start script had one inside two strings and did not. Neither reported
 * anything useful, and the failing line was byte-identical to the working one,
 * which is what made this take so long to see.
 *
 * UTF-8 with BOM is what PowerShell 5.1 detects reliably. PowerShell 7 defaults
